import React, { useState, useEffect } from "react";
import { useParams } from "react-router-dom";
import "bootstrap/dist/css/bootstrap.min.css";
import { FaPlus } from "react-icons/fa"; // Ícone de "+" para adicionar curso

const AdmInfAluno = () => {
  const { id } = useParams(); // Obtém o ID do aluno pela URL
  const [aluno, setAluno] = useState(null);
  const [curso, setCurso] = useState(null);
  const [listaCursos, setListaCursos] = useState([]);
  const [cursoSelecionado, setCursoSelecionado] = useState("");
  const [modoEdicao, setModoEdicao] = useState(false); // Controla se está editando

  useEffect(() => {
    const fetchAluno = async () => {
      try {
        const resposta = await fetch(`http://localhost:5000/alunos/${id}`);
        if (resposta.ok) {
          const dados = await resposta.json();
          setAluno(dados);
          setCurso(dados.curso); // Define o curso do aluno, se existir
        } else {
          console.error("Erro ao buscar aluno");
        }
      } catch (error) {
        console.error("Erro na requisição:", error);
      }
    };

    const fetchCursos = async () => {
      try {
        const resposta = await fetch(`http://localhost:5000/cursos`);
        if (resposta.ok) {
          const dados = await resposta.json();
          setListaCursos(dados);
        } else {
          console.error("Erro ao buscar cursos");
        }
      } catch (error) {
        console.error("Erro na requisição de cursos:", error);
      }
    };

    fetchAluno();
    fetchCursos();
  }, [id]);

  const adicionarCurso = async () => {
    if (!cursoSelecionado) return;

    try {
      const resposta = await fetch(`http://localhost:5000/alunos/${id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ curso: cursoSelecionado }),
      });

      if (resposta.ok) {
        setCurso(cursoSelecionado); // Atualiza o estado local com o curso selecionado
        setModoEdicao(false); // Sai do modo de edição após salvar
      } else {
        console.error("Erro ao adicionar curso");
      }
    } catch (error) {
      console.error("Erro na requisição:", error);
    }
  };

  if (!aluno) return <p className="text-center mt-4">Carregando...</p>;

  return (
    <div
      className="container mt-4 p-4"
      style={{ background: "#eaf2f8", borderRadius: "8px" }}
    >
      <h1 className="text-primary">EducaWeb</h1>

      {/* Nome do aluno */}
      <h2>{aluno.nome}</h2>

      <div className="d-flex justify-content-between align-items-center">
        <h5 className="fw-bold">informação do aluno</h5>
        <button className="btn btn-primary">Editar</button>
      </div>

      <div className="row mt-3">
        {/* Coluna do aluno */}
        <div className="col-md-6">
          <p>
            <strong>{aluno.nome}</strong>
          </p>
          <p>{aluno.email}</p>
          <p>{aluno.morada}</p>
          <p>{aluno.contacto}</p>
        </div>

        {/* Coluna do curso */}
        <div className="col-md-6">
          <div className="p-3 border rounded bg-white">
            <h5>Curso a frequentar</h5>

            {modoEdicao ? (
              <div>
                <select
                  className="form-control mb-2"
                  value={cursoSelecionado}
                  onChange={(e) => setCursoSelecionado(e.target.value)}
                >
                  <option value="">Selecione um curso</option>
                  {listaCursos.map((c) => (
                    <option key={c.id} value={c.nome}>
                      {c.nome}
                    </option>
                  ))}
                </select>
                <button
                  className="btn btn-success w-100"
                  onClick={adicionarCurso}
                >
                  Salvar
                </button>
              </div>
            ) : (
              <div className="d-flex align-items-center">
                <input
                  type="text"
                  className="form-control"
                  value={curso || "Nenhum curso"}
                  readOnly
                />
                {!curso && (
                  <button
                    className="btn btn-outline-secondary ms-2"
                    onClick={() => setModoEdicao(true)}
                  >
                    <FaPlus />
                  </button>
                )}
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Botões de ação */}
      <div className="mt-3 d-flex justify-content-end">
        <button className="btn btn-danger me-2">Cancelar</button>
        <button className="btn btn-primary">Salvar</button>
      </div>
    </div>
  );
};

export default AdmInfAluno;
